// VAT-exclusive teaching model. Components are additive and counted once.
export function deliveryBreakdown({sales,share,fee,perOrder,ticket,payment,ad=0}){const deliverySales=sales*share/100,orders=deliverySales*10000/ticket,commission=deliverySales*fee/100,logistics=orders*perOrder/10000,paymentCost=deliverySales*payment/100,advertising=deliverySales*ad/100;const total=commission+logistics+paymentCost+advertising;return {deliverySales,orders,commission,logistics,paymentCost,advertising,total,effectiveRate:deliverySales?total/deliverySales*100:0};}
export function orderComparison(ticket){const payment=ticket*.03;const old={commission:ticket*.098,logistics:2900,payment},now={commission:ticket*.078,logistics:3400,payment};old.total=old.commission+old.logistics+payment;now.total=now.commission+now.logistics+payment;return {old,now,delta:now.total-old.total};}
